import * as T from './vendor/three.module.js';
import {steer} from './navigation.js';
import {statusStep,canSense} from './combat-rules.js';
export function chapterTwoCombat({root,camera,free,blocked,rand,route=(n,t)=>t}){const shots=[],pools=[],tells=[];let time=0;
 const cleanup=o=>{o.removeFromParent();o.geometry?.dispose();o.material?.dispose()};
 function circle(pos,r,color){const m=new T.Mesh(new T.RingGeometry(r*.93,r,48),new T.MeshBasicMaterial({color,side:T.DoubleSide,transparent:true,opacity:.8,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.copy(pos).setY(.05);root().add(m);return m}
 function bolt(n,{angle=0,damage=18,ice=false,life=false}={}){const pos=n.g.position.clone().add(new T.Vector3(0,1.45,0)),dir=camera.position.clone().sub(pos).normalize().applyAxisAngle(new T.Vector3(0,1,0),angle),arrow=n.role==='crossbow';const m=new T.Mesh(arrow?new T.CylinderGeometry(.014,.014,.65,5):new T.IcosahedronGeometry(life?.18:.14,1),new T.MeshBasicMaterial({color:arrow?0xc7b995:life?0xe51e6a:ice?0x90ddff:0xff6f36}));m.position.copy(pos);root().add(m);shots.push({m,v:dir.multiplyScalar(arrow?35:life?27:25),age:0,damage,arrow,life,ice,owner:n.id,level:n.fixedLevel})}
 function pool(pos){const m=circle(pos,3.3,0xcf274c);pools.push({m,age:0,exposure:0})}
 function los(n){const p=n.g.position.clone().setY(1.4);for(let t=.04;t<1;t+=.04)if(blocked(p.clone().lerp(camera.position,t)))return false;return true}
 function tick(dt,mobs,{onDamage,onSlow=()=>{},onSound=()=>{},lanterns=0,spawnAdds=()=>{}}){time+=dt;for(const n of mobs){if(n.hp<=0)continue;const step=statusStep(n,dt);n.cooldown=Math.max(0,n.cooldown-step);n.blockLeft=Math.max(0,(n.blockLeft||0)-step);n.blockReady=Math.max(0,(n.blockReady||0)-step);n.specialReady=Math.max(0,(n.specialReady||0)-step);const d=Math.hypot(n.g.position.x-camera.position.x,n.g.position.z-camera.position.z),boss=n.role==='vampire',ranged=['mage','crossbow'].includes(n.role),sense=canSense(n,camera,d,boss?37:ranged?24:13);if(!n.aggro&&sense)n.aggro=camera.position.clone();if(n.aggro&&camera.position.distanceTo(n.aggro)>85&&!boss)n.aggro=null;if(boss&&n.aggro){n.phase=n.hp<n.maxHp*.4?2:1;if(n.phase===2&&!n.addsUsed){n.addsUsed=true;n.shieldLeft=10;spawnAdds(n);onSound('ice')}n.shieldLeft=Math.max(0,(n.shieldLeft||0)-dt);if(lanterns>=2)n.shieldLeft=0}if(!step){n.update(0);continue}
 if(n.windup>0){n.windup=Math.max(0,n.windup-step);if(!n.windup&&n.aggro){const kind=n.pending;if(kind==='pool'){tells.push({m:circle(camera.position,3.3,0xffe19a),age:0,position:camera.position.clone()});onSound('fireball')}else if(kind==='dash'){const dir=camera.position.clone().sub(n.g.position).setY(0).normalize();for(let i=0;i<12;i++){const x=n.g.position.x+dir.x*.6,z=n.g.position.z+dir.z*.6;if(!free(x,z,.6))break;n.g.position.set(x,0,z)}if(camera.position.distanceTo(n.g.position.clone().setY(1.7))<3)onDamage(23,'magic',n.id);onSound('ice')}else if(kind==='drain'){for(const a of [-.16,0,.16])bolt(n,{angle:a,damage:12,life:true});onSound('fireball')}else if(ranged){bolt(n,{damage:n.role==='mage'?21:19,ice:n.role==='mage'&&rand()<.3});if(n.role==='crossbow'&&rand()<.25)for(const a of [-.1,.1])bolt(n,{angle:a,damage:15});onSound(n.role==='mage'?'fireball':'bow')}else if(d<3.1&&los(n)){onDamage(boss?26:n.role==='warden'?25:21,'physical',n.id);onSound('sword')}}}
 else if(n.aggro){n.heading=Math.atan2(camera.position.x-n.g.position.x,camera.position.z-n.g.position.z);if(!n.root){if(!ranged){if(d>2.35){const goal=n.zone==='manor'&&n.g.position.z< -139&&camera.position.z> -139?new T.Vector3(3200,0,-135):n.zone==='manor'&&n.g.position.z> -139&&camera.position.z< -139?new T.Vector3(3200,0,-145):camera.position;steer(n,route(n,goal),boss?4.2:n.role==='warden'?2.7:3.1,step,free,()=>true,.43)}}else{const dx=(n.g.position.x-camera.position.x)/(d||1),dz=(n.g.position.z-camera.position.z)/(d||1),want=d<7?-1:d>19?1:0,target=new T.Vector3(n.g.position.x-dx*want*4+dz*Math.sin(time)*2,0,n.g.position.z-dz*want*4-dx*Math.sin(time)*2);steer(n,route(n,d>19?camera.position:target),2.3,step,free,()=>true,.4)}}n.heading=Math.atan2(camera.position.x-n.g.position.x,camera.position.z-n.g.position.z);if(n.role==='warden'&&!n.blockLeft&&n.blockReady===0){n.blockLeft=2;n.blockReady=7}if(!n.cooldown&&d<(boss?43:ranged?39:2.9)&&los(n)){n.pending=boss?(n.specialReady===0?(rand()<.5?'pool':'dash'):'drain'):'normal';if(boss&&d<3.1&&rand()<.55)n.pending='normal';if(boss&&['dash','pool'].includes(n.pending))n.specialReady=9;n.windup=n.pending==='normal'?.4:n.pending==='pool'?1.05:.75;n.cooldown=boss?(n.phase===2?1.7:2.1):ranged?2.5:1.4;n.cueAttack(ranged?n.role:boss?'mage':'sword',.7)}}else{n.timer-=step;if(n.timer<=0){n.timer=3+rand()*3;n.target.copy(n.home).add(new T.Vector3((rand()-.5)*7,0,(rand()-.5)*7))}steer(n,n.target,.75,step,free,()=>true,.4)}if(n.shield)n.shield.rotation.y=n.blockLeft?0:.7;n.update(step)}
 for(let i=tells.length-1;i>=0;i--){const t=tells[i];t.age+=dt;t.m.rotation.z+=dt*2;if(t.age>=1.15){pool(t.position);cleanup(t.m);tells.splice(i,1)}}for(let i=pools.length-1;i>=0;i--){const p=pools[i];p.age+=dt;p.m.material.opacity=.4+.2*Math.sin(time*6);if(Math.hypot(camera.position.x-p.m.position.x,camera.position.z-p.m.position.z)<3.3){p.exposure+=dt;if(p.exposure>=1){p.exposure-=1;onDamage(12,'hazard','ch2-vampire')}}else p.exposure=0;if(p.age>7){cleanup(p.m);pools.splice(i,1)}}
 for(let i=shots.length-1;i>=0;i--){const b=shots[i],old=b.m.position.clone();b.age+=dt;if(b.arrow)b.v.y-=2.5*dt;b.m.position.addScaledVector(b.v,dt);b.m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),b.v.clone().normalize());let hit=false,wall=false;const steps=Math.max(1,Math.ceil(old.distanceTo(b.m.position)/.15));for(let j=1;j<=steps;j++){const p=old.clone().lerp(b.m.position,j/steps);if(blocked(p)){wall=true;break}if(p.distanceTo(camera.position)<.5){hit=true;break}}if(hit){const applied=onDamage(b.damage*(b.life?1:1.1),b.arrow?'physical':'magic',b.owner);if(applied!==false){if(b.ice)onSlow(3);if(b.life&&lanterns<2){const owner=mobs.find(n=>n.id===b.owner);if(owner?.hp>0)owner.hp=Math.min(owner.maxHp,owner.hp+5)}}}if(hit||wall||b.age>5||b.m.position.y<0){cleanup(b.m);shots.splice(i,1)}}}
 function clear(){for(const b of shots)cleanup(b.m);for(const p of pools)cleanup(p.m);for(const t of tells)cleanup(t.m);shots.length=pools.length=tells.length=0}
 return {tick,clear,receive(n,amount){return amount*(n.role&&n.role!=='vampire'?.9:1)*(n.blockLeft>0?.4:1)*(n.shieldLeft>0?.7:1)},snapshot:()=>({time,shots:shots.map(b=>({position:b.m.position.toArray(),velocity:b.v.toArray(),age:b.age,damage:b.damage,arrow:b.arrow,life:b.life,ice:b.ice,owner:b.owner,level:b.level})),pools:pools.map(p=>({position:p.m.position.toArray(),age:p.age,exposure:p.exposure})),tells:tells.map(t=>({position:t.position.toArray(),age:t.age}))}),restore(s){clear();time=s?.time||0;for(const b of s?.shots||[]){const m=new T.Mesh(new T.IcosahedronGeometry(.15),new T.MeshBasicMaterial({color:b.life?0xe51e6a:b.ice?0x90ddff:0xff6f36}));m.position.fromArray(b.position);root().add(m);shots.push({...b,m,v:new T.Vector3().fromArray(b.velocity)})}for(const p of s?.pools||[]){const m=circle(new T.Vector3().fromArray(p.position),3.3,0xcf274c);pools.push({...p,m})}for(const t of s?.tells||[]){const position=new T.Vector3().fromArray(t.position),m=circle(position,3.3,0xffe19a);tells.push({...t,m,position})}}};
}
